PINNED = {'phone_host.py': '21b9139454ff32c6afc7a4f0c9dece4540cc4cc9eb1d2a619c8e895f2b8afdce', 'phone_mobile.py': '76e56ec9644284d94cec6539ef70fd246b6f03917704f000cd020b58b2739c03', 'phone_account.py': '3c4c9f9cccaeaa60a41cc3ff3fdde68c04372aabcd8861098cefb8d918406f81', 'phone_sources.json': '1e8a54e5baff2e9f77aa48e1335dea650ae74cc1e5ebfaf562d796960d0838c7', 'phone_remote.py': 'f891e8cc8c8e822eb7f75ccd22d441b4b451162de0bf87a134b3c925e9073e97', 'phone_service.py': 'dbb7bbf8fc4526b77d86496b8c73081e8a62cd2a4ea89a8e25ffd35e1969fe14', 'phone_migrate.py': 'aafbe024259d3f4dffc81b9b4ec7c9e9307a3487efeb969b1feed257f66399fb', 'phone_migration_sources.json': '214293c5bf0d7fd79838b1037ab9499a2a5428c91758fe3df7c439d790e3691d', 'phone_remote_check.py': '7d20cb6dcbbd2d784dab6c9fd8131722175d2f684b2202c3499fc13e8fd194d1', 'phone_clock.py': 'c1465b5e7d796937e16897c28d29d6ea78d4523b1c3a235a3384a97c2af7074c', 'phone_connection_trace.py': '7bd09c14dca5a97069448106800b2afa640620e8e33472f440b7ec34afec68fb', 'phone_public_ws.py': 'ba48a1e7dfc866545f9d67d81cde2bd14786bf45feb0333705bc3c171a2a5a95', 'phone_performance.py': '11a2f7648e97f0eaa52e53561aca97cc9fa656020fbe4842dedb850c1ac5e146', 'phone_signal_cache.py': '071eb2defa234b3055d439ab775e8c9ec0384b8f36b8d0464d241ac442d94827', 'phone_update.py': '1b67d65da9f908f2f50ea2bff53c35da3ead4cadef6c1664a07b21c7b24f7560', 'phone_update_ui.js': 'db7e902358753679a89de868b75b0b269cd0517de33bf1ed614df33359b2c6d9', 'phone_button_upgrade.py': '9e494a3c675910321268850a1fae9d578e0ca90f20bc7d16b8ef3c8421e02e6c', 'phone_button_old_sources.json': '358f3ec1c15643e5507d0670bee0cb7ff662b9d28a3f5a1e28d9ebe6418e6706', 'phone_handover.py': '11d26680baa581043998005af8b2016a40a4df1eff7730d9d34b10706c89523c', 'phone_pullback_size.py': '556c076220d5af838cd6082a224388f1ac23869fd7f0c479a220d2f381887f41', 'phone_candidate_fast.py': '131cf37b9868d67f0445c538e1cbf476ac490c491c25d521f744447cb71f21d5'}
